@cuda.jit
def _d256_update_stage(source, output, sidecar):
    sample = cuda.blockIdx.x
    task = cuda.blockIdx.y
    if task < 3:
        tile_row = 1
        tile_col = task + 1
    elif task < 5:
        tile_row = 2
        tile_col = task - 1
    else:
        tile_row = 3
        tile_col = 3
    sample_base = sample * _D256_MATRIX_ELEMENTS
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    accumulator = shared[0:_D256_FP32_TILE_ELEMENTS]
    update_start = _D256_FP32_TILE_ELEMENTS
    update_shared = shared[
        update_start : update_start + _D256_HALF_TILE_ELEMENTS
    ].view(np.float16)
    first = update_shared[0:_D256_HALF_TILE_ELEMENTS]
    second = update_shared[
        _D256_HALF_TILE_ELEMENTS : 2 * _D256_HALF_TILE_ELEMENTS
    ]
    if tile_row == tile_col:
        _d256_load_update_tile_async(
            source,
            sidecar,
            sample,
            sample_base,
            tile_row,
            tile_col,
            accumulator,
            0,
            tile_row,
            first,
        )
        _d256_gemm.execute(
            -1.0, first, first, 1.0, accumulator
        )
    else:
        _d256_load_update_pair_async(
            source,
            sidecar,
            sample,
            sample_base,
            tile_row,
            tile_col,
            accumulator,
            0,
            tile_row,
            first,
            tile_col,
            second,
        )
        _d256_gemm.execute(
            -1.0, first, second, 1.0, accumulator
        )
    cuda.syncthreads()
    if task == 0:
        local_info = accumulator[
            _D256_FP32_TILE_ELEMENTS - 4 : _D256_FP32_TILE_ELEMENTS - 3
        ].view(np.int32)
        _d256_cholesky.factorize(
            accumulator, local_info, lda=_D256_FP32_LD
        )
    _d256_store_tile(
        accumulator,
        output,
        sample_base,
        tile_row,
        tile_col,
        tile_row == tile_col,
    )


