@cuda.jit
def _d256_final_update_factor_cooperative(output, flags):
    sample = cuda.blockIdx.x
    task = cuda.blockIdx.y
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    if task < 3:
        accumulator = shared[0:_D256_FINAL_UPDATE_TILE_ELEMENTS]
        half_panels = shared[
            _D256_FINAL_UPDATE_TILE_ELEMENTS :
            _D256_FINAL_UPDATE_TILE_ELEMENTS
            + _D256_FINAL_SOLVE_TILE_ELEMENTS
        ].view(np.float16)
        first = half_panels[0:_D256_FINAL_SOLVE_TILE_ELEMENTS]
        second = half_panels[
            _D256_FINAL_SOLVE_TILE_ELEMENTS :
            2 * _D256_FINAL_SOLVE_TILE_ELEMENTS
        ]
        _d256_load_final_update_tile(
            get_array_ptr(accumulator),
            get_array_ptr(first),
            get_array_ptr(second),
            get_array_ptr(output),
        )
        _dx_cp_async_wait()
        cuda.syncthreads()
        if task != 1:
            second = first
        _d256_final_update_gemm.execute(
            -1.0, first, second, 1.0, accumulator
        )
        cuda.syncthreads()
        _d256_store_final_update_tile(
            get_array_ptr(accumulator), get_array_ptr(output)
        )
        cuda.threadfence()
        cuda.syncthreads()
        if cuda.threadIdx.x == 0:
            cuda.atomic.add(flags, sample, 1)
    else:
        if cuda.threadIdx.x == 0:
            while cuda.atomic.add(flags, sample, 0) != 3:
                pass
        cuda.syncthreads()
        factor = shared[0:_D256_FP32_TILE_ELEMENTS]
        _d256_cp_async_final_factor(
            get_array_ptr(factor), get_array_ptr(output)
        )
        _dx_cp_async_wait()
        cuda.syncthreads()
        local_info = factor[
            _D256_FP32_TILE_ELEMENTS - 4 : _D256_FP32_TILE_ELEMENTS - 3
        ].view(np.int32)
        _d256_cholesky.factorize(
            factor, local_info, lda=_D256_FP32_LD
        )
        cuda.syncthreads()
        _d256_store_final_upper_tile(
            get_array_ptr(factor), get_array_ptr(output)
        )
        cuda.threadfence()
        cuda.syncthreads()
        if cuda.threadIdx.x == 0:
            cuda.atomic.exch(flags, sample, 0)


