extern "C" __device__
void d256_load_final_update_tile(
        float* accumulator,
        __half* operand,
        const float* output) {
    constexpr int fp32_ld = 36;
    constexpr int half_ld = 72;
    constexpr int output_ld = 256;
    constexpr long long matrix_elements = 256LL * 256LL;
    const int sample = blockIdx.x;
    const int task = blockIdx.y;
    const int tile_row = task >> 1;
    const int tile_col = (task + 1) >> 1;
    const long long accumulator_index =
        sample * matrix_elements + 3 * 64 * 256 + 3 * 64
        + tile_row * 32 * 256 + tile_col * 32;
    const long long operand_index =
        sample * matrix_elements + 2 * 64 * 256 + 3 * 64;

    const int fp32_row = threadIdx.x >> 3;
    const int fp32_col = (threadIdx.x & 7) * 4;
    const unsigned accumulator_base = static_cast<unsigned>(
        __cvta_generic_to_shared(accumulator));
    #pragma unroll
    for (int load = 0; load < 2; ++load) {
        const int current_row = fp32_row + load * 16;
        const unsigned shared_offset = static_cast<unsigned>(
            (current_row * fp32_ld + fp32_col) * sizeof(float));
        const unsigned destination_shared =
            accumulator_base + shared_offset;
        const float* source_global =
            output + accumulator_index + current_row * output_ld + fp32_col;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(destination_shared), "l"(source_global));
    }

    const int half_row = threadIdx.x >> 4;
    const int half_col = (threadIdx.x & 15) * 4;
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = half_row + load * 8;
        const float4 values = *reinterpret_cast<const float4*>(
            output + operand_index + current_row * output_ld + half_col);
        __half2* packed = reinterpret_cast<__half2*>(
            operand + current_row * half_ld + half_col);
        packed[0] = __floats2half2_rn(values.x, values.y);
        packed[1] = __floats2half2_rn(values.z, values.w);
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

